    val tree = value.toXdrJsonElement()
    assertEquals(true, isJsonString(tree))
    val decoded = ClaimableBalanceIDXdr.fromXdrJsonElement(tree)
    assertEquals(value.discriminant, decoded.discriminant)
    assertEquals(tree, decoded.toXdrJsonElement())
  }

  @Test
  fun claimableBalanceIDXdrRejectsAnArmItDoesNotDeclare() {
    assertFailsWith<IllegalArgumentException> {
      ClaimableBalanceIDXdr.fromXdrJsonElement(buildJsonObject { put("not_a_name_this_type_declares", JsonNull) })
    }
    assertFailsWith<IllegalArgumentException> {
      ClaimableBalanceIDXdr.fromXdrJsonElement(
        buildJsonObject {
          put("not_a_name_this_type_declares", JsonNull)
          put("not_a_name_this_type_declares_too", JsonNull)
        }
      )
    }
    assertFailsWith<IllegalArgumentException> { ClaimableBalanceIDXdr.fromXdrJsonElement(JsonNull) }
  }

